-- Keep raw readings; exclude negative and 0.1 readings consistently from display, averages and alerts.
ALTER TABLE mrtb
    MODIFY COLUMN recosi_value DOUBLE AS (CASE WHEN REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') AS DOUBLE) NOT IN (0, 0.001, 0.01, 0.1) AND CAST(REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') AS DOUBLE) > 0 THEN CAST(REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') AS DOUBLE) ELSE NULL END) PERSISTENT,
    MODIFY COLUMN recosi_unmeasured TINYINT(1) AS (CASE WHEN REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') AS DOUBLE) <= 0 THEN 1 WHEN REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') AS DOUBLE) IN (0.001, 0.01, 0.1) THEN 1 ELSE 0 END) PERSISTENT,
    MODIFY COLUMN coldtp_value DOUBLE AS (CASE WHEN REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') AS DOUBLE) NOT IN (0, 0.001, 0.01, 0.1) AND CAST(REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') AS DOUBLE) > 0 THEN CAST(REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') AS DOUBLE) ELSE NULL END) PERSISTENT,
    MODIFY COLUMN coldtp_unmeasured TINYINT(1) AS (CASE WHEN REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') AS DOUBLE) <= 0 THEN 1 WHEN REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') AS DOUBLE) IN (0.001, 0.01, 0.1) THEN 1 ELSE 0 END) PERSISTENT,
