    MODIFY COLUMN recoru_unmeasured TINYINT(1) AS (CASE WHEN REGEXP_REPLACE(TRIM(`recoru`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`recoru`), '[^0-9.+-]', '') AS DOUBLE) <= 0 THEN 1 WHEN REGEXP_REPLACE(TRIM(`recoru`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`recoru`), '[^0-9.+-]', '') AS DOUBLE) IN (0.001, 0.01, 0.1) THEN 1 ELSE 0 END) PERSISTENT,
