    MODIFY COLUMN gctemp_value DOUBLE AS (CASE WHEN REGEXP_REPLACE(TRIM(`gctemp`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`gctemp`), '[^0-9.+-]', '') AS DOUBLE) NOT IN (0, 0.001, 0.01, 0.1) AND CAST(REGEXP_REPLACE(TRIM(`gctemp`), '[^0-9.+-]', '') AS DOUBLE) > 0 THEN CAST(REGEXP_REPLACE(TRIM(`gctemp`), '[^0-9.+-]', '') AS DOUBLE) ELSE NULL END) PERSISTENT,
