-- Retain historical events, but stop outstanding notifications for invalid measurements.
UPDATE alert_event e JOIN alert_rule r ON r.id=e.rule_id
SET e.recovered_at=CURRENT_TIMESTAMP(6),
    e.delivery_status=CASE WHEN e.delivery_status IN ('PENDING','FAILED','PARTIAL') THEN 'SKIPPED' ELSE e.delivery_status END
WHERE r.rule_type='RANGE' AND e.event_type IN ('LOW','HIGH')
  AND e.recovered_at IS NULL
  AND (e.measured_value<=0 OR e.measured_value IN (0.001,0.01,0.1));
